{"code": "const fs = await import("node:fs");
const cur = fs.readFileSync("D:\\lean\\AUDIT_LEDGER.md", "utf8");
const head = fs.readFileSync("D:\\lean\\tmp\\_head_ledger.md", "utf8");
const curLines = cur.split(/\r?\n/);
const headLines = head.split(/\r?\n/);
console.log("cur lines", curLines.length, "head lines", headLines.length);
// find my entry start
const idx = curLines.findIndex(l => l.startsWith("## S1977:"));
console.log("S1977 entry at line index", idx);
// compare current[0..idx) with head prefix
let match = 0;
while (match < idx && match < headLines.length && curLines[match] === headLines[match]) match++;
console.log("common prefix with HEAD:", match);
// do the current (pre-entry) lines appear in head at all (as a subsequence of a prefix)?
const pre = curLines.slice(0, idx);
// count how many of the pre lines occur in head
const headSet = new Set(headLines);
let inHead = pre.filter(l => headSet.has(l)).length;
console.log("pre lines found somewhere in HEAD:", inHead, "/", pre.length);
// last 30 lines before my entry
console.log("---- last 30 pre-entry lines ----");
console.log(pre.slice(-30).map((l,i)=>`${pre.length-30+i+1}\t${l}`).join("\n"));
console.log("---- head (HEAD file) last 20 ----");
console.log(headLines.slice(-22).join("\n"));
console.log("---- current first 12 ----");
console.log(curLines.slice(0,12).join("\n"));
console.log("---- HEAD first 12 ----");
console.log(headLines.slice(0,12).join("\n"));
", "description": "Compare current ledger with HEAD version"}

